package net.civeira.phylax.common.security;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;

import net.civeira.phylax.common.security.impl.InvocationSourceImpl;

@DisplayName("InvocationSource default methods")
class InvocationSourceDefaultsUnitTest {

  @ParameterizedTest(name = "{0}")
  @EnumSource(InvocationChannel.class)
  @DisplayName("Should classify every channel")
  void shouldClassifyChannel(InvocationChannel channel) {
    // Arrange — a source on the given channel
    InvocationSource source = InvocationSourceImpl.builder().channel(channel).build();

    // Act / Assert — each predicate reflects the channel
    boolean interactive = channel == InvocationChannel.WEB || channel == InvocationChannel.MOBILE
        || channel == InvocationChannel.DESKTOP;
    assertEquals(interactive, source.isInteractive());
    assertEquals(channel == InvocationChannel.BATCH, source.isBatch());
    assertEquals(channel == InvocationChannel.API, source.isApi());
    assertEquals(channel == InvocationChannel.INTERNAL, source.isInternal());
    assertEquals(channel != InvocationChannel.INTERNAL, source.isRemote());
  }
}
